insert into tournaments (id, sport_id, host_university_id, title_en, title_ka, summary_en, summary_ka, format_en, format_ka, status, start_date, end_date, venue_en, venue_ka, city_en, city_ka, level, fee, slots, slots_taken, registration_deadline, image_url) values
  ('btu-padel-cup', 'padel', 'btu', 'BTU Padel Cup', 'BTU-ს პადელის თასი', 'Two days of mixed doubles on four courts. Group stage on Saturday, knockout on Sunday.', 'ორი დღე შერეული წყვილების ოთხ კორტზე. შაბათს ჯგუფური ეტაპი, კვირას ნოკაუტი.', 'Mixed doubles · groups into knockout', 'შერეული წყვილები · ჯგუფები და ნოკაუტი', 'registration_open', '2026-11-15', '2026-11-16', 'Padel Park Saburtalo', 'პადელ პარკი, საბურთალო', 'Tbilisi', 'თბილისი', 'open', 40, 32, 18, '2026-11-10', null),
  ('freeuni-padel-ladder', 'padel', 'freeuni', 'Free University Padel Ladder', 'თავისუფალი უნივერსიტეტის პადელის კიბე', 'A rolling ladder that runs all term. Challenge the pair above you, swap places if you win.', 'მოძრავი კიბე, რომელიც მთელ სემესტრს გრძელდება. გამოიწვიე ზემოთ მდგომი წყვილი და მოგების შემთხვევაში ადგილი გაცვალეთ.', 'Doubles ladder · challenge format', 'წყვილების კიბე · გამოწვევის ფორმატი', 'ongoing', '2026-10-05', '2026-12-14', 'Padel Park Saburtalo', 'პადელ პარკი, საბურთალო', 'Tbilisi', 'თბილისი', 'intermediate', null, 24, 24, null, null),
  ('gau-padel-beginners', 'padel', 'gau', 'GAU Beginners Padel Night', 'GAU-ს დამწყებთა პადელის საღამო', 'Never held a racket? Start here. Coaches run a short clinic, then everyone plays short sets.', 'ჯერ არასდროს გეჭირა რაკეტი? დაიწყე აქედან. მწვრთნელები ატარებენ მოკლე გაკვეთილს, შემდეგ ყველა თამაშობს მოკლე სეტებს.', 'Clinic + short sets', 'გაკვეთილი + მოკლე სეტები', 'registration_open', '2026-11-08', '2026-11-08', 'GAU Courts, Merab Aleksidze St', 'GAU-ს კორტები, მერაბ ალექსიძის ქ.', 'Tbilisi', 'თბილისი', 'beginner', 25, 16, 9, '2026-11-05', null),
  ('student-padel-night', 'padel', null, 'Tbilisi Student Padel Night', 'თბილისის სტუდენტური პადელის ღამე', 'Open to every campus. Pairs are drawn on the night, so come alone or bring a partner.', 'ღიაა ყველა კამპუსისთვის. წყვილები ადგილზე ისაზღვრება — მოდი მარტო ან პარტნიორთან ერთად.', 'Open draw · random pairs', 'ღია ბადე · შემთხვევითი წყვილები', 'registration_open', '2026-11-22', '2026-11-22', 'Padel Park Saburtalo', 'პადელ პარკი, საბურთალო', 'Tbilisi', 'თბილისი', 'open', 30, 40, 27, '2026-11-18', null),
  ('cu-padel-open', 'padel', 'cu', 'Caucasus Padel Open', 'კავკასიის პადელის ოფენი', 'The strongest draw of the term, seeded from ladder results across the participating campuses.', 'სემესტრის ყველაზე ძლიერი ბადე, დათესილი მონაწილე კამპუსების კიბის შედეგებიდან.', 'Seeded doubles knockout', 'დათესილი წყვილების ნოკაუტი', 'upcoming', '2026-12-06', '2026-12-07', 'Padel Park Dighomi', 'პადელ პარკი, დიღომი', 'Tbilisi', 'თბილისი', 'advanced', 50, 32, 0, '2026-11-28', null),
  ('btu-football-league', 'football', 'btu', 'BTU Football League', 'BTU-ს ფეხბურთის ლიგა', 'The federation league: twenty-five student clubs across five groups, then a knockout for the title.', 'ფედერაციის ლიგა: ოცდახუთი სტუდენტური კლუბი ხუთ ჯგუფად, შემდეგ ნოკაუტი ტიტულისთვის.', 'Five groups of five · knockout final', 'ხუთი ხუთგუნდიანი ჯგუფი · ნოკაუტ ფინალი', 'finished', '2026-06-07', '2026-08-23', 'BTU Campus Pitch', 'BTU-ს კამპუსის მოედანი', 'Tbilisi', 'თბილისი', 'open', null, 25, 25, null, null),
  ('tsu-futsal-cup', 'football', 'tsu', 'TSU Autumn Futsal Cup', 'TSU-ს შემოდგომის ფუტსალის თასი', 'Five-a-side indoors over one weekend. Squads of up to ten, two group stages then a final.', 'ხუთზე ხუთი დახურულ დარბაზში ერთი შაბათ-კვირის განმავლობაში. ათკაციანი შემადგენლობები, ორი ჯგუფური ეტაპი და ფინალი.', '5-a-side · squads of 10', '5x5 · ათკაციანი შემადგენლობა', 'registration_open', '2026-11-14', '2026-11-15', 'TSU Sports Hall', 'TSU-ს სპორტული დარბაზი', 'Tbilisi', 'თბილისი', 'open', 150, 16, 11, '2026-11-09', null),
  ('gtu-faculty-league', 'football', 'gtu', 'GTU Faculty League', 'GTU-ს ფაკულტეტების ლიგა', 'Faculty against faculty, seven-a-side, one fixture a week through to the December final.', 'ფაკულტეტი ფაკულტეტის წინააღმდეგ, შვიდზე შვიდი, კვირაში ერთი მატჩი დეკემბრის ფინალამდე.', '7-a-side · weekly fixtures', '7x7 · ყოველკვირეული მატჩები', 'ongoing', '2026-09-28', '2026-12-20', 'GTU Pitch No. 1', 'GTU-ს მოედანი №1', 'Tbilisi', 'თბილისი', 'open', null, 12, 12, null, null),
  ('iliauni-winter-cup', 'football', 'iliauni', 'Ilia State Winter Cup', 'ილიაუნის ზამთრის თასი', 'Eleven-a-side on the covered pitch over two January weekends. Entries open in December.', 'თერთმეტზე თერთმეტი დახურულ მოედანზე ორ იანვრის შაბათ-კვირას. განაცხადები დეკემბერში იხსნება.', '11-a-side · knockout', '11x11 · ნოკაუტი', 'upcoming', '2027-01-17', '2027-01-24', 'Ilia State Stadium', 'ილიაუნის სტადიონი', 'Tbilisi', 'თბილისი', 'open', 200, 8, 0, '2027-01-10', null),
  ('agruni-freshers-cup', 'football', 'agruni', 'AgrUni Freshers Cup', 'აგრარულის პირველკურსელთა თასი', 'First-years only, five-a-side, played over a single afternoon at the start of term.', 'მხოლოდ პირველკურსელებისთვის, ხუთზე ხუთი, ერთ შუადღეში სემესტრის დასაწყისში.', '5-a-side · first-years only', '5x5 · მხოლოდ პირველკურსელები', 'finished', '2026-10-03', '2026-10-04', 'AgrUni Campus Pitch', 'აგრარულის კამპუსის მოედანი', 'Tbilisi', 'თბილისი', 'beginner', null, 12, 12, null, null)
