insert into news (id, slug, title_en, title_ka, excerpt_en, excerpt_ka, body_en, body_ka, sport_id, university_id, published_at, is_announcement, read_minutes, image_url) values
  ('btu-padel-cup-open', 'btu-padel-cup-registration-open', 'BTU Padel Cup registration is open', 'BTU-ს პადელის თასზე რეგისტრაცია გახსნილია', 'Eighteen of thirty-two places are already taken. Entries close on 10 November.', 'ოცდათორმეტიდან თვრამეტი ადგილი უკვე დაკავებულია. რეგისტრაცია 10 ნოემბერს იხურება.', 'BTU opens its autumn padel cup to students from every campus on the hub. The draw is mixed doubles, with a Saturday group stage across four courts and the knockout rounds on Sunday. Entry is 40 GEL per player and includes court time, balls and a shirt. Pick your university on the registration form so the organisers can seed the groups fairly.', 'BTU შემოდგომის პადელის თასს ხსნის ჰაბზე წარმოდგენილი ყველა კამპუსის სტუდენტისთვის. ბადე შერეული წყვილებისაა: შაბათს ჯგუფური ეტაპი ოთხ კორტზე, კვირას კი ნოკაუტი. მონაწილეობის საფასური მოთამაშეზე 40 ლარია და მოიცავს კორტის დროს, ბურთებს და მაისურს. რეგისტრაციისას მიუთითე შენი უნივერსიტეტი, რომ ორგანიზატორებმა ჯგუფები სამართლიანად დათესონ.', 'padel', 'btu', '2026-10-22T10:00:00+04:00', true, 2, null),
  ('tsu-futsal-entries', 'tsu-futsal-cup-entries-close-soon', 'TSU futsal cup entries close on 9 November', 'TSU-ს ფუტსალის თასზე განაცხადები 9 ნოემბერს იხურება', 'Eleven squads of a possible sixteen have entered the autumn five-a-side weekend.', 'შემოდგომის 5x5 შაბათ-კვირაზე შესაძლო თექვსმეტიდან თერთმეტმა გუნდმა დაასახელა შემადგენლობა.', 'Tbilisi State University hosts its autumn futsal cup over the weekend of 14 November. Squads may register up to ten players and the entry fee is 150 GEL per team, split however the squad likes. Group stages run on Saturday morning, with the final on Sunday evening. Squads from other universities are welcome — the form asks which campus you represent.', 'თბილისის სახელმწიფო უნივერსიტეტი შემოდგომის ფუტსალის თასს 14 ნოემბრის შაბათ-კვირას მასპინძლობს. გუნდს შეუძლია ათ მოთამაშემდე დაარეგისტრიროს, მონაწილეობის საფასური კი გუნდზე 150 ლარია და შიგნით როგორც გინდათ, ისე გაინაწილეთ. ჯგუფური ეტაპები შაბათს დილით ჩატარდება, ფინალი კი კვირას საღამოს. სხვა უნივერსიტეტების გუნდებიც მოწვეულნი არიან — ფორმაში მიუთითებთ, რომელ კამპუსს წარმოადგენთ.', 'football', 'tsu', '2026-10-21T15:30:00+04:00', true, 2, null),
  ('new-padel-courts', 'two-new-padel-courts-open-at-saburtalo', 'Two new padel courts open at Saburtalo', 'საბურთალოზე ორი ახალი პადელის კორტი გაიხსნა', 'Weekday mornings are free for students with a university ID from November.', 'ნოემბრიდან სამუშაო დღეების დილის საათები უფასოა სტუდენტური ბარათის მქონეთათვის.', 'Padel Park Saburtalo has added two covered courts, taking the venue to six. Free weekday morning slots between 08:00 and 12:00 have been agreed for students holding a university ID, bookable through each campus sports office. The extra capacity is what allows the BTU cup to run four courts in parallel next month.', 'პადელ პარკ საბურთალოს დაემატა ორი დახურული კორტი და ობიექტზე ჯამში ექვსი გახდა. სამუშაო დღეებში 08:00-დან 12:00-მდე უფასო სლოტები შეთანხმდა სტუდენტური ბარათის მქონე სტუდენტებისთვის, დაჯავშნა კი თითოეული კამპუსის სპორტის ოფისის მეშვეობითაა შესაძლებელი. სწორედ დამატებული სიმძლავრე იძლევა იმის საშუალებას, რომ BTU-ს თასმა მომავალ თვეში ოთხი კორტი პარალელურად გამოიყენოს.', 'padel', 'freeuni', '2026-10-20T09:00:00+04:00', true, 3, null),
  ('gtu-faculty-league-halfway', 'gtu-faculty-league-reaches-halfway', 'GTU faculty league reaches the halfway point', 'GTU-ს ფაკულტეტების ლიგამ ნახევარს მიაღწია', 'Twelve faculties, one fixture a week, and an informatics side that has not dropped a game.', 'თორმეტი ფაკულტეტი, კვირაში ერთი მატჩი და ინფორმატიკის გუნდი, რომელსაც ჯერ არცერთი თამაში არ წაუგია.', 'Georgian Technical University runs its faculty league every Saturday from late September to the December final. Informatics have won all six of their fixtures so far, with architecture and civil engineering level behind them. The league is free to enter but closed to the faculties already registered this term; the next intake opens in February.', 'საქართველოს ტექნიკური უნივერსიტეტი ფაკულტეტების ლიგას ყოველ შაბათს ატარებს სექტემბრის ბოლოდან დეკემბრის ფინალამდე. ინფორმატიკის გუნდმა ექვსივე მატჩი მოიგო, არქიტექტურა და სამოქალაქო ინჟინერია კი თანაბარი მაჩვენებლით მისდევენ. ლიგაში მონაწილეობა უფასოა, თუმცა ამ სემესტრში რეგისტრაცია უკვე დახურულია; შემდეგი მიღება თებერვალში გაიხსნება.', 'football', 'gtu', '2026-10-19T18:00:00+04:00', false, 3, null),
  ('gau-beginners-night', 'gau-beginners-padel-night-returns', 'GAU beginners padel night returns in November', 'GAU-ს დამწყებთა პადელის საღამო ნოემბერში ბრუნდება', 'Rackets provided, no experience needed, sixteen places and nine already gone.', 'რაკეტები ადგილზეა, გამოცდილება არ სჭირდება — თექვსმეტი ადგილიდან ცხრა უკვე დაკავებულია.', 'The Georgian American University runs the friendliest entry point on the hub: a short coached clinic followed by short sets, with rackets and balls provided. It costs 25 GEL and is capped at sixteen so that nobody spends the evening waiting. Students from any university can register — just pick your campus on the form.', 'საქართველოს ამერიკული უნივერსიტეტი ჰაბზე ყველაზე მეგობრულ შესვლის წერტილს სთავაზობს: მოკლე სავარჯიშო მწვრთნელთან და შემდეგ მოკლე სეტები, რაკეტებითა და ბურთებით უზრუნველყოფით. ღირს 25 ლარი და ლიმიტი თექვსმეტია, რომ არავინ გაატაროს საღამო ლოდინში. რეგისტრაცია ნებისმიერი უნივერსიტეტის სტუდენტს შეუძლია — უბრალოდ აირჩიე შენი კამპუსი ფორმაში.', 'padel', 'gau', '2026-10-18T12:00:00+04:00', false, 2, null),
  ('iliauni-winter-cup-announced', 'ilia-state-announces-winter-football-cup', 'Ilia State announces its winter football cup', 'ილიაუნიმ ზამთრის ფეხბურთის თასი გამოაცხადა', 'Eleven-a-side on the covered pitch across two January weekends. Entries open in December.', 'თერთმეტზე თერთმეტი დახურულ მოედანზე ორ იანვრის შაბათ-კვირას. განაცხადები დეკემბერში იხსნება.', 'Ilia State University will stage an eight-team knockout on its covered pitch over the weekends of 17 and 24 January. Entry is 200 GEL per squad and registration opens in December, closing on 10 January. The university has said half the places are reserved for squads from other campuses.', 'ილიას სახელმწიფო უნივერსიტეტი რვაგუნდიან ნოკაუტს ჩაატარებს დახურულ მოედანზე 17 და 24 იანვრის შაბათ-კვირას. მონაწილეობის საფასური გუნდზე 200 ლარია, რეგისტრაცია დეკემბერში იხსნება და 10 იანვარს იხურება. უნივერსიტეტის განცხადებით, ადგილების ნახევარი სხვა კამპუსების გუნდებისთვისაა დათმობილი.', 'football', 'iliauni', '2026-10-17T11:00:00+04:00', true, 2, null),
  ('cu-padel-open-seeding', 'caucasus-padel-open-seeding-explained', 'How the Caucasus Padel Open seeding works', 'როგორ მუშაობს კავკასიის პადელის ოფენის თესვა', 'December’s strongest draw takes its seeds from ladder results across every campus.', 'დეკემბრის ყველაზე ძლიერი ბადე თესვას ყველა კამპუსის კიბის შედეგებიდან იღებს.', 'Caucasus University has published how it will seed the December open. Pairs are ranked on their results in their own campus ladders over the autumn term, which means a pair from a smaller programme can still be seeded highly. Entries cost 50 GEL and close on 28 November, and the draw is published two days later.', 'კავკასიის უნივერსიტეტმა გამოაქვეყნა, როგორ დათესავს დეკემბრის ოფენს. წყვილები რანჟირდება შემოდგომის სემესტრში საკუთარი კამპუსის კიბეზე ნაჩვენები შედეგებით, რაც ნიშნავს, რომ პატარა პროგრამის წყვილიც შეიძლება მაღლა დაითესოს. მონაწილეობა 50 ლარი ღირს, განაცხადები 28 ნოემბერს იხურება, ბადე კი ორი დღის შემდეგ ქვეყნდება.', 'padel', 'cu', '2026-10-16T14:00:00+04:00', false, 3, null),
  ('hub-expansion', 'two-more-universities-join-the-hub', 'Two more universities join the hub in spring', 'გაზაფხულზე ჰაბს კიდევ ორი უნივერსიტეტი შეუერთდება', 'Ten campuses will be publishing their tournaments, events and news here from February.', 'თებერვლიდან ათი კამპუსი გამოაქვეყნებს აქ თავის ტურნირებს, ივენთებსა და სიახლეებს.', 'From February the hub will carry ten universities rather than eight, including the first two from outside Tbilisi. Each campus keeps control of what it publishes — its own tournaments, its own registration deadlines, its own announcements — and students filter the site down to whichever universities they care about.', 'თებერვლიდან ჰაბზე რვის ნაცვლად ათი უნივერსიტეტი იქნება, მათ შორის პირველი ორი თბილისის გარედან. თითოეული კამპუსი თავად აკონტროლებს, რას აქვეყნებს — საკუთარ ტურნირებს, საკუთარ ვადებს, საკუთარ განცხადებებს — სტუდენტები კი საიტს იმ უნივერსიტეტებზე ფილტრავენ, რომლებიც მათ აინტერესებთ.', null, null, '2026-10-14T11:00:00+04:00', true, 2, null)
on conflict (id) do update set
